function getZabbixTranslation(key, lang) {
    if (zabbixTranslations[lang] && zabbixTranslations[lang][key]) {
        return zabbixTranslations[lang][key];
    }
    if (zabbixTranslations.en && zabbixTranslations.en[key]) {
        return zabbixTranslations.en[key];
    }
    return null;
}

function applyZabbixTranslations(lang) {
    console.log('Applying zabbix translations for:', lang);
    let count = 0;
    document.querySelectorAll('[data-i18n]').forEach(element => {
        const key = element.getAttribute('data-i18n');
        if (key && key.startsWith('review.zabbix.')) {
            const translation = getZabbixTranslation(key, lang);
            if (translation) {
                element.textContent = translation;
                count++;
            }
        }
    });
    console.log(`Applied ${count} zabbix translations`);
}

window.addEventListener('languageChanged', (e) => {
    const lang = e.detail.language;
    setTimeout(() => applyZabbixTranslations(lang), 200);
});

if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => {
        const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
        applyZabbixTranslations(currentLang);
    });
} else {
    const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
    applyZabbixTranslations(currentLang);
}

console.log('zabbix i18n loaded');
